export type Cell = [number, number];

function isNeighbor([x, y]: Cell, [otherX, otherY]: Cell): boolean {
  return (
    Math.abs(x - otherX) <= 1 &&
    Math.abs(y - otherY) <= 1 &&
    !(x === otherX && y === otherY)
  );
}

function countLiveNeighbors(cell: Cell, cells: Cell[]): number {
  return cells.filter((other) => isNeighbor(cell, other)).length;
}

function isAlive(cell: Cell, cells: Cell[]): boolean {
  return cells.some((other) => other[0] === cell[0] && other[1] === cell[1]);
}

function neighborsOf([x, y]: Cell): Cell[] {
  return [-1, 0, 1].flatMap((dx) =>
    [-1, 0, 1]
      .filter((dy) => !(dx === 0 && dy === 0))
      .map((dy): Cell => [x + dx, y + dy]),
  );
}

function candidates(cells: Cell[]): Cell[] {
  const all = cells.flatMap((cell) => [cell, ...neighborsOf(cell)]);
  return all.filter(
    (cell, index) => all.findIndex((other) => isSame(cell, other)) === index,
  );
}

function isSame([x, y]: Cell, [otherX, otherY]: Cell): boolean {
  return x === otherX && y === otherY;
}

function survives(cell: Cell, cells: Cell[]): boolean {
  const liveNeighborCount = countLiveNeighbors(cell, cells);
  if (isAlive(cell, cells)) {
    return liveNeighborCount === 2 || liveNeighborCount === 3;
  }
  return liveNeighborCount === 3;
}

export function nextGeneration(cells: Cell[]): Cell[] {
  return candidates(cells).filter((cell) => survives(cell, cells));
}

